import java.util.*;

class Solution {
    public int kthSmallest(TreeNode root, int k) {
        List<Integer> list = new ArrayList<>();
        inorder(root, list);
        return list.get(k - 1);   // 注意是 k-1
    }

    private void inorder(TreeNode node, List<Integer> list) {
        if (node == null) return;
        inorder(node.left, list);
        list.add(node.val);
        inorder(node.right, list);
    }
}

class Solution {
    private int count = 0;
    private int ans = 0;

    public int kthSmallest(TreeNode root, int k) {
        inorder(root, k);
        return ans;
    }

    // 返回 true 表示已找到，让整条调用链立刻返回
    private boolean inorder(TreeNode node, int k) {
        if (node == null) return false;

        if (inorder(node.left, k)) return true;   // 左子树已找到，短路

        count++;
        if (count == k) {
            ans = node.val;
            return true;
        }

        return inorder(node.right, k);
    }
}

import java.util.*;

class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        int count = 0;

        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;          // 一路向左
            }
            cur = stack.pop();           // 弹出时才是中序顺序
            count++;
            if (count == k) return cur.val;   // 直接返回，无需层层传递
            cur = cur.right;
        }
        return -1;   // 题目保证 k 合法，不会到这里
    }
}
